"""Bài đọc theo cấp độ (nội dung tự biên soạn). Mỗi bài: tiêu đề, level, chủ đề, đoạn văn, từ vựng, câu hỏi trắc nghiệm."""
import re


def R(title, level, topic, paragraphs, vocab, questions):
    text = " ".join(paragraphs)
    return {
        "kind": "reading", "title": title, "slug": re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-"),
        "level": level, "topic": topic, "text": paragraphs,
        "vocabulary": [{"word": w, "vi": v} for w, v in vocab],
        "questions": [{"q": q, "options": o, "answer": a} for q, o, a in questions],
        "word_count": len(re.findall(r"[A-Za-z']+", text)), "question_count": len(questions),
    }


